import type {
    API,
    ASTNode,
    FileInfo,
    ObjectProperty,
    Property,
} from "jscodeshift"
import { getStringValue } from "../ast-helpers"

export const name = path.basename(__filename, path.extname(__filename))
export const description =
    "remove redundant `driver: require(\"expo-sqlite\")` from Expo data sources"

/**
 * Returns true when `node` is exactly the call expression `require("expo-sqlite")`
 * — a plain call to `require` with a single `"expo-sqlite"` string argument.
 *
 * Deliberately narrow: a member access such as `require("expo-sqlite").default`
 * is a MemberExpression (not a CallExpression), an identifier/variable is an
 * Identifier, and `require("some-other-pkg")` carries a different argument — all
 * of which fall through and leave the `driver` property untouched.
 */
const isRequireExpoSqlite = (node: ASTNode): boolean => {
    if (node.type !== "CallExpression") return false
    if (
        node.callee.type !== "Identifier" ||
        node.callee.name !== "require"
    ) {
        return false
    }
    if (node.arguments.length !== 1) return false
    const [arg] = node.arguments
    return getStringValue(arg) === "expo-sqlite"
}

export const datasourceExpo = (file: FileInfo, api: API) => {
    const j = api.jscodeshift
    const root = j(file.source)

    let hasChanges = false

    // Scope to ObjectExpressions that look like TypeORM Expo DataSource
    // options — they carry both `type: "expo"` and a sibling `database`
    // property. Requiring `database` avoids false positives on unrelated
    // `{ type: "expo" }` objects. String-literal keys (`"type"`) are handled
    // alongside identifier keys for ormconfig-style plain exports.
    root.find(j.ObjectExpression).forEach((objPath) => {
        let isExpo = false
        let hasDatabase = false

        for (const prop of objPath.node.properties) {
            if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
                continue
            }

            const keyName =
                prop.key.type === "Identifier"
                    ? prop.key.name
                    : getStringValue(prop.key)

            if (keyName === "type" && getStringValue(prop.value) === "expo") {
                isExpo = true
            } else if (keyName === "database") {
                hasDatabase = true
            }
        }

        if (!isExpo || !hasDatabase) return

        const originalLength = objPath.node.properties.length
        objPath.node.properties = objPath.node.properties.filter((prop) => {
            if (prop.type !== "Property" && prop.type !== "ObjectProperty") {
                return true
            }
            const typedProp = prop as ObjectProperty | Property
            const keyName =
                typedProp.key.type === "Identifier"
                    ? typedProp.key.name
                    : getStringValue(typedProp.key)

            if (
                keyName === "driver" &&
                isRequireExpoSqlite(typedProp.value as ASTNode)
            ) {
                return false
            }
            return true
        })

        if (objPath.node.properties.length !== originalLength) {
            hasChanges = true
        }
    })

    return hasChanges ? root.toSource() : undefined
}

